// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        // The deciding call must be made by an address that already has a balance.
        // We construct the scenario through the public API only.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.deal(actor, amount);

        vm.prank(actor);
        c.addToBalance{value: amount}();

        // Only withdraw if there is something to withdraw; otherwise both contracts
        // trivially revert on the zero-value send and the rule is vacuous.
        vm.assume(c.getBalance(actor) != 0);

        vm.prank(actor);
        try c.withdrawBalance() {
            // On the reference, the caller's balance is zeroed and the Ether is sent.
            // The mutant zeroes the balance but sends 0 Ether; from the caller's
            // perspective both zero the recorded balance, so we assert the invariant
            // that the CALLED contract's balance must decrease by exactly the
            // withdrawn amount.  The reference forwards the full balance; the mutant
            // forwards 0.
            assertTrue(address(c).balance == 0);
        } catch {
            // A revert here is admissible: the reference itself reverts when the
            // Ether transfer fails.  This branch is not the distinguishing case.
            assertTrue(true);
        }
    }
}
